// DOT 3 (27/10/2026): nang 395 why Doc/Nghe dang cu ("Doan N: ...") len khuon u7.
// Chi doi cac cau chua co whyU7; why goc giu nguyen trong whyOrig, khong sua noi
// dung goc. Khuon hien thi: Vi du: <su kien>. Vi vay dap an "..." dung.
// Cach lam: <phuong phap theo ho dang>. Cau nao khong co why thi bo qua.
(function () {
  function u7Method(q, listen) {
    var t = q.type || "";
    if (t === "TFNG" || t === "TF" || t === "YNNG") return listen ? "nghe kỹ rồi đối chiếu từng ý trong câu hỏi với những gì nghe được. Nghe đúng như vậy thì câu này đúng." : "đối chiếu từng ý trong câu hỏi với đúng câu trong bài. Bài nói đúng như vậy thì câu này đúng.";
    if (q.options || q.o) return listen ? "nghe kỹ câu hỏi rồi tìm chỗ trong đoạn nghe nói giống đáp án. Đáp án nghe quen nhưng đoạn nghe không nói thì không chọn." : "đọc kỹ câu hỏi rồi tìm đúng câu trong bài nói giống đáp án. Đáp án nghe quen nhưng bài không nói thì không chọn.";
    return listen ? "tìm chỗ trong đoạn nghe nói tới ý này rồi điền đúng từ trong đoạn nghe, đừng điền từ mình đoán." : "tìm đúng chỗ trong bài nói tới ý này rồi điền đúng từ trong bài, đừng điền từ mình đoán.";
  }
  function u7Answer(q) {
    var opts = q.options || q.o;
    if (opts && opts[q.a] !== undefined) return String(opts[q.a]);
    if (typeof q.answer === "string") return q.answer.split("|")[0];
    if (typeof q.a === "string") return q.a;
    return "";
  }
  function u7Clean(s) {
    s = String(s || "").replace(/^Đoạn\s*\d+\s*:\s*/, "");
    s = s.replace(/→/g, "").replace(/\s+/g, " ").trim();
    s = s.replace(/[.\"”\s]+$/, "");
    return s;
  }
  function u7Upgrade(list, listen) {
    (list || []).forEach(function (b) {
      (b.questions || []).forEach(function (q) {
        if (!q || q.whyU7 === true) return;
        var fact = u7Clean(q.why);
        if (!fact) return;
        var ans = u7Clean(u7Answer(q));
        q.whyOrig = q.why;
        q.why = "Ví dụ: " + fact + ". Vì vậy đáp án “" + ans + "” đúng. Cách làm: " + u7Method(q, listen);
        q.whyU7 = true;
      });
    });
  }
  try {
    if (typeof CONTENT !== "undefined" && CONTENT) {
      u7Upgrade(CONTENT.reading);
      u7Upgrade(CONTENT.listeningPlus, true);
    }
  } catch (e) {}
})();

// DOT 3 (27/10/2026): thong nhat quy uoc 不 truoc thanh 4 = bú (bien thanh chuan).
// Quy tac nay von da duoc day trong bai ngu phap 不会 ("不 truoc 会 (thanh 4) doc
// thanh bú") va batch pha 3 da ap dung; kho cu con sot 28 cho "bù + thanh 4" trong
// truong pinyin (huì/shì/yòng/xiàng/bàn/kàn/pà/yào/dà) + 1 cho dinh bùguò (不过).
// Patch nay CHI sua cac truong pinyin (pinyin/py/modelPy) cua module Trung va the
// tu Trung, giu nguyen dau cau hoa; KHONG dung toi dap an trac nghiem (vi du cac
// lua chon bùdébù/búdébù), loi giai thich, van xuoi, hay noi dung tieng Anh.
// Luu y cho batch sau: patch chay o cuoi file nen chi sua du lieu den thoi diem
// nay; batch moi phai viet thang bú truoc thanh 4 ngay tu luc soan.
(function () {
  var PAIRS = [
    ["bù huì", "bú huì"], ["bù shì", "bú shì"], ["bù yòng", "bú yòng"],
    ["bù xiàng", "bú xiàng"], ["bù bàn", "bú bàn"], ["bù kàn", "bú kàn"],
    ["bù pà", "bú pà"], ["bù yào", "bú yào"], ["bù dà", "bú dà"],
    ["bùguò", "búguò"]
  ];
  function patchStr(s) {
    var out = s;
    PAIRS.forEach(function (pr) {
      var re = new RegExp(pr[0].replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "g");
      out = out.replace(re, function (m) {
        return (m.charAt(0) === "B" ? pr[1].charAt(0).toUpperCase() + pr[1].slice(1) : pr[1]);
      });
      var reCap = new RegExp(pr[0].charAt(0).toUpperCase() + pr[0].slice(1).replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "g");
      out = out.replace(reCap, function () { return pr[1].charAt(0).toUpperCase() + pr[1].slice(1); });
    });
    return out;
  }
  function walkPy(obj) {
    if (!obj || typeof obj !== "object") return;
    if (Array.isArray(obj)) { obj.forEach(walkPy); return; }
    Object.keys(obj).forEach(function (k) {
      if ((k === "pinyin" || k === "py" || k === "modelPy") && typeof obj[k] === "string") obj[k] = patchStr(obj[k]);
      else walkPy(obj[k]);
    });
  }
  try {
    if (typeof ZH_GRAMMAR !== "undefined") walkPy(ZH_GRAMMAR);
    if (typeof ZH_READING !== "undefined") walkPy(ZH_READING);
    if (typeof ZH_LISTENING !== "undefined") walkPy(ZH_LISTENING);
    if (typeof ZH_SPEAK !== "undefined") walkPy(ZH_SPEAK);
    if (typeof ZH_ROLE !== "undefined") walkPy(ZH_ROLE);
    if (typeof ZH_WRITE !== "undefined") walkPy(ZH_WRITE);
    if (typeof CONTENT !== "undefined" && CONTENT && CONTENT.zhVocab) walkPy(CONTENT.zhVocab);
  } catch (e) {}
})();
